import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const mount=document.querySelector('#scene');
const scene=new THREE.Scene();scene.background=new THREE.Color(0xa9e3dc);scene.fog=new THREE.Fog(0xa9e3dc,35,145);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,220);camera.position.set(0,5.2,10.5);
const renderer=new THREE.WebGLRenderer({antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.2;mount.appendChild(renderer.domElement);
scene.add(new THREE.HemisphereLight(0xeaffeb,0x538b82,2));const sun=new THREE.DirectionalLight(0xfff0cc,3.2);sun.position.set(-5,12,8);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);scene.add(sun);
const mat=(color,rough=.72)=>new THREE.MeshStandardMaterial({color,roughness:rough});
const waterMat=mat(0x64c4b8,.32),roadMat=mat(0xe2dfae),roadEdgeMat=mat(0xf4b95d),whiteMat=mat(0xfff8df),darkMat=mat(0x214542),beakMat=mat(0xf28b3f),goldMat=new THREE.MeshStandardMaterial({color:0xffc847,metalness:.16,roughness:.3,emissive:0x5c3100,emissiveIntensity:.13});
const water=new THREE.Mesh(new THREE.PlaneGeometry(240,260),waterMat);water.rotation.x=-Math.PI/2;water.position.set(0,-2.05,-75);water.receiveShadow=true;scene.add(water);
const track=[];for(let i=0;i<9;i++){const g=new THREE.Group();const deck=new THREE.Mesh(new THREE.BoxGeometry(12,.34,17),roadMat);deck.position.y=-1.35;deck.receiveShadow=true;deck.castShadow=true;g.add(deck);const trim=new THREE.Mesh(new THREE.BoxGeometry(12.25,.25,17.2),roadEdgeMat);trim.position.y=-1.58;g.add(trim);for(let x of [-5.4,5.4]){const rail=new THREE.Mesh(new THREE.BoxGeometry(.12,.22,17),whiteMat);rail.position.set(x,-1.12,0);g.add(rail)}g.position.z=-i*16;scene.add(g);track.push(g)}
// Soft, low-poly scenery gives the pond a playful sense of scale.
const scenery=[];const reedMat=mat(0x6da77c),flowerMats=[mat(0xfff3c6),mat(0xf4a58c),mat(0xf8d76c)];
function makeIsland(x,z){const g=new THREE.Group();const pad=new THREE.Mesh(new THREE.CylinderGeometry(.8,1.05,.25,9),mat(0x4ea996));pad.position.y=-1.86;g.add(pad);const flower=new THREE.Mesh(new THREE.SphereGeometry(.18,8,6),flowerMats[Math.floor(Math.random()*flowerMats.length)]);flower.position.set((Math.random()-.5)*.8,-1.68,(Math.random()-.5)*.8);g.add(flower);g.position.set(x,0,z);scene.add(g);scenery.push(g)}
for(let i=0;i<26;i++)makeIsland((Math.random()<.5?-1:1)*(9+Math.random()*18),-Math.random()*155);
const cloudMat=new THREE.MeshBasicMaterial({color:0xf1ffed,transparent:true,opacity:.65});for(let i=0;i<8;i++){const c=new THREE.Group();for(let j=0;j<4;j++){const puff=new THREE.Mesh(new THREE.SphereGeometry(1,12,8),cloudMat);puff.scale.set(1.6+Math.random(),.45+Math.random()*.25,.6);puff.position.x=j*1.25;c.add(puff)}c.position.set((Math.random()-.5)*50,8+Math.random()*9,-30-Math.random()*100);scene.add(c)}
const duckColors=[0xffd34d,0xf5a4ba,0x9eafff,0x8ed3a2,0xf5f2e7,0xb487e8];const skinNames=['Sunny','Peaches','Bubbles','Minty','Snowy','Berry'];let skinIndex=0;
function makeDuck(color){const root=new THREE.Group();const yellow=mat(color),wingMat=new THREE.MeshStandardMaterial({color,roughness:.85});function ball(parent,m,x,y,z,sx,sy,sz){const o=new THREE.Mesh(new THREE.SphereGeometry(1,20,16),m);o.position.set(x,y,z);o.scale.set(sx,sy,sz);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o}
 ball(root,yellow,0,.78,0,.66,.57,.84);ball(root,yellow,0,1.43,-.35,.49,.5,.5);ball(root,beakMat,0,1.31,-.85,.29,.12,.28);
 for(const side of [-1,1]){ball(root,wingMat,side*.56,.83,-.02,.18,.31,.52).rotation.z=side*-.24;ball(root,whiteMat,side*.29,1.53,-.76,.115,.145,.09);ball(root,darkMat,side*.31,1.53,-.835,.055,.085,.045);ball(root,whiteMat,side*.325,1.56,-.87,.02,.025,.015);const foot=ball(root,beakMat,side*.27,.26,.1,.18,.09,.34);foot.rotation.x=.15}
 const tail=ball(root,yellow,0,.91,.77,.24,.18,.3);tail.rotation.x=-.3;root.traverse(o=>{if(o.isMesh){o.castShadow=true}});scene.add(root);return root}
let duck=makeDuck(duckColors[0]);
// A few sparkle motes drift around the swimmer.
const glints=[];for(let i=0;i<35;i++){const m=new THREE.Mesh(new THREE.SphereGeometry(.035+Math.random()*.035,8,6),new THREE.MeshBasicMaterial({color:i%3===0?0xffe281:0xe9fff2,transparent:true,opacity:.68}));m.position.set((Math.random()-.5)*22,-1.8+Math.random()*4,-Math.random()*100);scene.add(m);glints.push(m)}
const entities=[];let nextSpawn=-18;const ringGeo=new THREE.TorusGeometry(.92,.12,12,32);const starGeo=new THREE.OctahedronGeometry(.42,0);const obstacleGeo=new THREE.SphereGeometry(.55,14,10);
function addEntity(type,x,y,z){let mesh;if(type==='ring'){mesh=new THREE.Mesh(ringGeo,goldMat);mesh.material=goldMat;const inner=new THREE.Mesh(new THREE.TorusGeometry(.68,.045,8,28),new THREE.MeshBasicMaterial({color:0xfff3b1}));mesh.add(inner);for(let i=0;i<3;i++){const dot=new THREE.Mesh(new THREE.SphereGeometry(.075,8,6),new THREE.MeshBasicMaterial({color:0xffe79a}));const a=i*2.094;dot.position.set(Math.cos(a)*.78,Math.sin(a)*.78,0);mesh.add(dot)}}else if(type==='star'){mesh=new THREE.Mesh(starGeo,new THREE.MeshStandardMaterial({color:0xfff08a,emissive:0xf5a921,emissiveIntensity:.65,roughness:.3}))}else{mesh=new THREE.Group();const rock=new THREE.Mesh(obstacleGeo,mat(0x8dbb75));rock.scale.set(1.2,.72,.8);rock.castShadow=true;mesh.add(rock);const pad=new THREE.Mesh(new THREE.CylinderGeometry(.8,.95,.18,9),mat(0x448d79));pad.position.y=-.38;mesh.add(pad);const flower=new THREE.Mesh(new THREE.SphereGeometry(.15,8,6),mat(0xffd66b));flower.position.set(.13,.25,-.08);mesh.add(flower)}mesh.position.set(x,y,z);mesh.castShadow=true;scene.add(mesh);entities.push({mesh,type,hit:false,phase:Math.random()*6})}
function spawnPattern(z){const lane=()=>THREE.MathUtils.randFloat(-4.3,4.3);const y=()=>THREE.MathUtils.randFloat(.55,2.4);const roll=Math.random();if(roll<.47){const x=lane(),h=y();addEntity('ring',x,h,z);addEntity('star',x+(Math.random()-.5)*.5,h+1.5,z-5)}else if(roll<.76){addEntity('star',lane(),y(),z);addEntity('star',lane(),y(),z-5);addEntity('star',lane(),y(),z-10)}else{addEntity('obstacle',lane(),-.72,z);addEntity('ring',lane(),y(),z-8)}}
const keys=new Set(),touch=new Set();let running=false,paused=false,score=0,distance=0,lives=3,speed=19,boost=0,boostCooldown=0,invuln=0,comboCount=0,gameTime=0,lastTime=0,toastTimer=0;
const scoreEl=document.querySelector('#score'),distanceEl=document.querySelector('#distance'),fillEl=document.querySelector('#distance-fill'),comboEl=document.querySelector('#combo'),toastEl=document.querySelector('#toast');
const skinsEl=document.querySelector('#skins');duckColors.forEach((c,i)=>{const b=document.createElement('button');b.className='skin'+(i===0?' selected':'');b.title=skinNames[i]+' — unlocked';b.setAttribute('aria-label',skinNames[i]+' duck, unlocked');b.innerHTML='🦆';b.style.filter=`hue-rotate(${i*46}deg) saturate(${i===4?.2:1})`;b.addEventListener('click',()=>{skinIndex=i;document.querySelectorAll('.skin').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');scene.remove(duck);duck=makeDuck(duckColors[i])});skinsEl.appendChild(b)});
function setHearts(){document.querySelectorAll('#hearts span').forEach((e,i)=>e.classList.toggle('lost',i>=lives))}
function showToast(text){toastEl.textContent=text;toastEl.classList.add('show');toastTimer=1.2}
function startGame(){score=0;distance=0;lives=3;speed=19;boost=0;boostCooldown=0;invuln=0;comboCount=0;gameTime=0;nextSpawn=-25;for(const e of entities)scene.remove(e.mesh);entities.length=0;for(let i=0;i<5;i++)spawnPattern(-38-i*23);document.querySelector('#menu').classList.add('hidden');document.querySelector('#result-panel').classList.add('hidden');document.querySelector('#pause-panel').classList.add('hidden');document.querySelector('#game-shell').classList.add('playing');document.querySelector('#bottom-hint').classList.remove('hidden');document.querySelector('#pause-btn').style.display='grid';running=true;paused=false;scoreEl.textContent='00000';distanceEl.textContent='0';fillEl.style.width='0%';setHearts();showToast('READY, SET, QUACK!')}
function finish(){running=false;document.querySelector('#game-shell').classList.remove('playing');document.querySelector('#bottom-hint').classList.add('hidden');document.querySelector('#pause-btn').style.display='none';document.querySelector('#final-score').textContent=score.toLocaleString();document.querySelector('#result-title').textContent=score>450?'POND LEGEND':score>200?'SPLASH STAR':'NICE SWIM!';document.querySelector('#result-copy').textContent=`You paddled ${Math.floor(distance)} meters and found ${Math.floor(score/25)} shiny treasures.`;document.querySelector('#result-panel').classList.remove('hidden')}
function togglePause(){if(!running)return;paused=!paused;document.querySelector('#pause-panel').classList.toggle('hidden',!paused)}
document.querySelector('#play-btn').addEventListener('click',startGame);document.querySelector('#again-btn').addEventListener('click',startGame);document.querySelector('#resume-btn').addEventListener('click',togglePause);document.querySelector('#pause-btn').addEventListener('click',togglePause);
document.querySelector('#sound-btn').addEventListener('click',e=>{e.currentTarget.classList.toggle('muted');e.currentTarget.textContent=e.currentTarget.classList.contains('muted')?'♫̸':'♫';showToast(e.currentTarget.classList.contains('muted')?'SOUND OFF':'SOUND ON')});
window.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown',' ','Space'].includes(e.key))e.preventDefault();keys.add(e.key.toLowerCase());if(e.key==='Escape'||e.key.toLowerCase()==='p')togglePause()});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));document.querySelectorAll('[data-control]').forEach(btn=>{const key=btn.dataset.control;const down=e=>{e.preventDefault();touch.add(key)};const up=e=>{e.preventDefault();touch.delete(key)};btn.addEventListener('pointerdown',down);btn.addEventListener('pointerup',up);btn.addEventListener('pointercancel',up);btn.addEventListener('pointerleave',up)});
function held(...names){return names.some(n=>keys.has(n)||touch.has(n))}
function damage(){if(invuln>0)return;lives--;invuln=1.65;comboCount=0;setHearts();showToast('WHOOPS! WATCH THAT LILY');duck.position.y+=.15;if(lives<=0)finish()}

