  if(held(' ','space','dash')&&boostCooldown<=0){boost=.95;boostCooldown=3.1;showToast('QUACK ATTACK!')}
  boost=Math.max(0,boost-dt);boostCooldown=Math.max(0,boostCooldown-dt);invuln=Math.max(0,invuln-dt);const currentSpeed=speed+(boost>0?13:0);distance+=currentSpeed*dt*.47;score+=dt*2.1;speed=Math.min(25,speed+dt*.08);
  nextSpawn+=currentSpeed*dt;if(nextSpawn>17){nextSpawn-=THREE.MathUtils.randFloat(35,47);spawnPattern(-120)}
