   if(e.hit||m.position.z>17){scene.remove(m);e.remove=true}}
  for(let i=entities.length-1;i>=0;i--)if(entities[i].remove)entities.splice(i,1);
  scoreEl.textContent=String(Math.floor(score)).padStart(5,'0');distanceEl.textContent=String(Math.floor(distance));fillEl.style.width=`${Math.min(100,distance%500/5)}%`;if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)toastEl.classList.remove('show')}
 }
 const bob=Math.sin(gameTime*5)*.045;duck.position.y+=bob*(running&&!paused?1:0.35);duck.rotation.z=THREE.MathUtils.damp(duck.rotation.z,-(running?((held('arrowleft','a','left')?1:0)-(held('arrowright','d','right')?1:0))*.13:0),5,dt);duck.rotation.x=Math.sin(gameTime*3)*.035;
 if(invuln>0&&Math.floor(gameTime*14)%2===0)duck.visible=false;else duck.visible=true;
 camera.position.x=THREE.MathUtils.damp(camera.position.x,duck.position.x*.42,3.5,dt);camera.position.y=THREE.MathUtils.damp(camera.position.y,4.9+duck.position.y*.18,3,dt);camera.lookAt(duck.position.x*.25,.45,-8.5);
 glints.forEach((g,i)=>{g.position.z+=dt*(running&&!paused?speed*.55:1.3);if(g.position.z>12)g.position.z=-100-Math.random()*45;g.material.opacity=.35+Math.sin(gameTime*3+i)*.2});
 renderer.render(scene,camera)}
requestAnimationFrame(animate);
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.8))});

